#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const int N = 10;
    vector<vector<int>> a(N, vector<int>(N));

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (!(cin >> a[i][j])) return 0;
        }
    }

    vector<vector<int>> press(N, vector<int>(N, 0));

    auto inside = [&](int x, int y) {
        return x >= 0 && x < N && y >= 0 && y < N;
    };

    auto get = [&](int x, int y) {
        int v = a[x][y];
        const int dx[5] = {0, -1, 1, 0, 0};
        const int dy[5] = {0, 0, 0, -1, 1};
        for (int k = 0; k < 5; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (inside(nx, ny)) v += press[nx][ny];
        }
        return v % 2;
    };

    for (int i = 1; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (get(i - 1, j) == 1) {
                press[i][j] = 1;
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cout << press[i][j];
            if (j + 1 < N) cout << ' ';
        }
        cout << '\n';
    }

    return 0;
}

