void simulate() {
    int temp[10][10];
    memcpy(temp, grid, sizeof(grid));
    int count = 0;

    // Apply first row presses
    for (int j = 0; j < 10; j++) {
        if (press[0][j]) {
            count++;
            temp[0][j] ^= 1;
            if (j > 0) temp[0][j-1] ^= 1;
            if (j < 9) temp[0][j+1] ^= 1;
            if (1 < 10) temp[1][j] ^= 1;
        }
    }

    // For rows 1 to 9, determine presses based on row above
    for (int i = 1; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            if (temp[i-1][j] == 1) {
                press[i][j] = 1;
                count++;
                temp[i][j] ^= 1;
                if (j > 0) temp[i][j-1] ^= 1;
                if (j < 9) temp[i][j+1] ^= 1;
                if (i < 9) temp[i+1][j] ^= 1;
                temp[i-1][j] ^= 1;
            } else {
                press[i][j] = 0;
            }
        }
    }

    // Check if all are off
    int all_off = 1;
    for (int j = 0; j < 10; j++) {
        if (temp[9][j] == 1) {
            all_off = 0;
            break;
        }
    }

    if (all_off && count < min_presses) {
        min_presses = count;
        memcpy(best, press, sizeof(press));
    }
}

