int main() {
    int grid[10][10];
    for (int i = 0; i < 10; i++)
        for (int j = 0; j < 10; j++)
            scanf("%d", &grid[i][j]);

    // 100 equations, 100 unknowns over GF(2)
    // augmented matrix: 100 rows x 101 cols
    int A[100][101];
    memset(A, 0, sizeof(A));

    // Build matrix
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            int row = i*10 + j;
            // pressing (r,c) affects (i,j) if they are same or adjacent
            // So column for variable (r,c) in equation (i,j):
            // A[row][r*10+c] = 1 if (r,c) is (i,j) or neighbor
            A[row][row] = 1; // self
            if (i > 0) A[row][(i-1)*10+j] = 1;
            if (i < 9) A[row][(i+1)*10+j] = 1;
            if (j > 0) A[row][i*10+(j-1)] = 1;
            if (j < 9) A[row][i*10+(j+1)] = 1;
            // RHS: initial state (we want to cancel it, so rhs = grid[i][j])
            A[row][100] = grid[i][j];
        }
    }

    // Gaussian elimination over GF(2)
    int pivot_row[100];
    memset(pivot_row, -1, sizeof(pivot_row));
    int cur_row = 0;
    for (int col = 0; col < 100 && cur_row < 100; col++) {
        // find pivot
        int found = -1;
        for (int r = cur_row; r < 100; r++) {
            if (A[r][col]) { found = r; break; }
        }
        if (found == -1) continue;
        // swap
        for (int c = 0; c <= 100; c++) {
            int tmp = A[cur_row][c]; A[cur_row][c] = A[found][c]; A[found][c] = tmp;
        }
        pivot_row[col] = cur_row;
        // eliminate
        for (int r = 0; r < 100; r++) {
            if (r != cur_row && A[r][col]) {
                for (int c = 0; c <= 100; c++)
                    A[r][c] ^= A[cur_row][c];
            }
        }
        cur_row++;
    }

    // Extract solution
    int sol[100];
    memset(sol, 0, sizeof(sol));
    for (int col = 0; col < 100; col++) {
        if (pivot_row[col] != -1) {
            sol[col] = A[pivot_row[col]][100];
        }
    }

    // Output
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            if (j) printf(" ");
            printf("%d", sol[i*10+j]);
        }
        printf("\n");
    }

    return 0;
}

