int main(void) {
    int a[N][N];
    int press[N][N] = {0};

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (scanf("%d", &a[i][j]) != 1) return 0;
        }
    }

    /* Try all possibilities for the first row */
    for (int mask = 0; mask < (1 << N); mask++) {
        int p[N][N] = {0};

        for (int j = 0; j < N; j++) {
            p[0][j] = (mask >> j) & 1;
        }

        /* Determine presses row by row */
        for (int i = 1; i < N; i++) {
            for (int j = 0; j < N; j++) {
                int state = a[i - 1][j];
                state ^= p[i - 1][j];
                if (i - 2 >= 0) state ^= p[i - 2][j];
                if (j - 1 >= 0) state ^= p[i - 1][j - 1];
                if (j + 1 < N) state ^= p[i - 1][j + 1];

                /* If light above is still on, must press here */
                p[i][j] = state;
            }
        }

        /* Check whether last row becomes all off */
        int ok = 1;
        for (int j = 0; j < N; j++) {
            int state = a[N - 1][j];
            state ^= p[N - 1][j];
            state ^= p[N - 2][j];
            if (j - 1 >= 0) state ^= p[N - 1][j - 1];
            if (j + 1 < N) state ^= p[N - 1][j + 1];

            if (state != 0) {
                ok = 0;
                break;
            }
        }

        if (ok) {
            for (int i = 0; i < N; i++)
                for (int j = 0; j < N; j++)
                    press[i][j] = p[i][j];

            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (j) printf(" ");
                    printf("%d", press[i][j]);
                }
                printf("\n");
            }
            return 0;
        }
    }

    return 0;
}

