public class Main {
    static final int N = 10;
    static final int SIZE = N * N;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int[][] grid = new int[N][N];
        for (int i = 0; i < N; i++) {
            String line = br.readLine().trim();
            for (int j = 0; j < N; j++) {
                grid[i][j] = line.charAt(j) - '0';
            }
        }

        // Build linear system: A * x = b (mod 2)
        // x is vector of length 100 (press positions)
        // b is current state (goal: all zero)
        int[][] A = new int[SIZE][SIZE];
        int[] b = new int[SIZE];

        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                int idx = r * N + c;
                b[idx] = grid[r][c];
                // self
                A[idx][idx] = 1;
                // up
                if (r > 0) A[idx][(r-1)*N + c] = 1;
                // down
                if (r < N-1) A[idx][(r+1)*N + c] = 1;
                // left
                if (c > 0) A[idx][r*N + (c-1)] = 1;
                // right
                if (c < N-1) A[idx][r*N + (c+1)] = 1;
            }
        }

        // Gaussian elimination over GF(2)
        int[] x = solve(A, b);

        // Output result
        char[][] out = new char[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                out[i][j] = x[i * N + j] == 1 ? '1' : '0';
            }
            System.out.println(new String(out[i]));
        }
    }

    static int[] solve(int[][] A, int[] b) {
        int n = b.length;
        int[][] mat = new int[n][n+1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = A[i][j];
            }
            mat[i][n] = b[i];
        }

        int row = 0;
        for (int col = 0; col < n && row < n; col++) {
            int pivot = -1;
            for (int i = row; i < n; i++) {
                if (mat[i][col] == 1) {
                    pivot = i;
                    break;
                }
            }
            if (pivot == -1) continue;
            // swap rows
            int[] tmp = mat[row];
            mat[row] = mat[pivot];
            mat[pivot] = tmp;

            // eliminate other rows
            for (int i = 0; i < n; i++) {
                if (i != row && mat[i][col] == 1) {
                    for (int j = col; j <= n; j++) {
                        mat[i][j] ^= mat[row][j];
                    }
                }
            }
            row++;
        }

        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            int pivotCol = -1;
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    pivotCol = j;
                    break;
                }
            }
            if (pivotCol != -1) {
                res[pivotCol] = mat[i][n];
            }
        }
        return res;
    }
}

