public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = 10;
        int N = n * n;

        // Read the initial state
        int[] state = new int[N];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                state[i * n + j] = sc.nextInt();
            }
        }

        // Build the matrix for Lights Out
        // A[i][j] = 1 if pressing cell j affects cell i
        // We need A * x = state (mod 2)

        int[][] mat = new int[N][N + 1];

        int[] dr = {0, 0, 0, 1, -1};
        int[] dc = {0, 1, -1, 0, 0};

        for (int cell = 0; cell < N; cell++) {
            int r = cell / n;
            int c = cell % n;
            // pressing 'cell' affects cell and its neighbors
            for (int d = 0; d < 5; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    int affected = nr * n + nc;
                    mat[affected][cell] = 1;
                }
            }
        }

        // Set the RHS
        for (int i = 0; i < N; i++) {
            mat[i][N] = state[i];
        }

        // Gaussian elimination over GF(2)
        int[] pivotRow = new int[N];
        Arrays.fill(pivotRow, -1);
        int row = 0;
        for (int col = 0; col < N && row < N; col++) {
            // Find pivot
            int pivot = -1;
            for (int r = row; r < N; r++) {
                if (mat[r][col] == 1) {
                    pivot = r;
                    break;
                }
            }
            if (pivot == -1) continue;

            // Swap
            int[] tmp = mat[row];
            mat[row] = mat[pivot];
            mat[pivot] = tmp;

            pivotRow[col] = row;

            // Eliminate
            for (int r = 0; r < N; r++) {
                if (r != row && mat[r][col] == 1) {
                    for (int k = 0; k <= N; k++) {
                        mat[r][k] ^= mat[row][k];
                    }
                }
            }
            row++;
        }

        // Back substitution - since unique solution, just read off
        int[] x = new int[N];
        for (int col = 0; col < N; col++) {
            if (pivotRow[col] != -1) {
                x[col] = mat[pivotRow[col]][N];
            }
        }

        // Output
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j > 0) sb.append(" ");
                sb.append(x[i * n + j]);
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int N = 10;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int[][] a = new int[N][N];

        for (int i = 0; i < N; i++) {
            String line;
            while (true) {
                line = br.readLine();
                if (line == null) return;
                line = line.trim();
                if (!line.isEmpty()) break;
            }

            StringTokenizer st = new StringTokenizer(line);
            if (st.countTokens() == N) {
                for (int j = 0; j < N; j++) {
                    a[i][j] = Integer.parseInt(st.nextToken());
                }
            } else {
                // Handle input without spaces, e.g. 0101010101
                line = line.replaceAll("\\s+", "");
                for (int j = 0; j < N; j++) {
                    a[i][j] = line.charAt(j) - '0';
                }
            }
        }

        int[][] ans = solve(a);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (j > 0) sb.append(' ');
                sb.append(ans[i][j]);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }

    static int[][] solve(int[][] initial) {
        // Try all possibilities for the first row.
        for (int mask = 0; mask < (1 << N); mask++) {
            int[][] press = new int[N][N];

            for (int j = 0; j < N; j++) {
                press[0][j] = (mask >> j) & 1;
            }

            // Determine rows 1..9 so that row i-1 becomes all zero.
            for (int i = 1; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (state(initial, press, i - 1, j) == 1) {
                        press[i][j] = 1;
                    }
                }
            }

            boolean ok = true;
            for (int j = 0; j < N; j++) {
                if (state(initial, press, N - 1, j) == 1) {
                    ok = false;
                    break;
                }
            }

            if (ok) return press;
        }

        return new int[N][N]; // Problem guarantees exactly one solution.
    }

    static int state(int[][] initial, int[][] press, int x, int y) {
        int v = initial[x][y];
        v ^= press[x][y];
        if (x > 0) v ^= press[x - 1][y];
        if (x + 1 < N) v ^= press[x + 1][y];
        if (y > 0) v ^= press[x][y - 1];
        if (y + 1 < N) v ^= press[x][y + 1];
        return v;
    }
}

