    # press[r][c] = whether we send an axion through tube (r, c)
    press = [[0] * 10 for _ in range(10)]

    # Try all possibilities for the first row
    for first_mask in range(1 << 10):
        p = [[0] * 10 for _ in range(10)]

        for c in range(10):
            if (first_mask >> c) & 1:
                p[0][c] = 1

        # Determine presses row by row
        for r in range(1, 10):
            for c in range(10):
                # State of cell (r-1, c) after presses affecting it
                s = board[r-1][c]
                s ^= p[r-1][c]
                if r - 2 >= 0:
                    s ^= p[r-2][c]
                if c - 1 >= 0:
                    s ^= p[r-1][c-1]
                if c + 1 < 10:
                    s ^= p[r-1][c+1]

                # If still on, must press below it
                if s == 1:
                    p[r][c] = 1

        # Check last row
        ok = True
        r = 9
        for c in range(10):
            s = board[r][c]
            s ^= p[r][c]
            if r - 1 >= 0:
                s ^= p[r-1][c]
            if c - 1 >= 0:
                s ^= p[r][c-1]
            if c + 1 < 10:
                s ^= p[r][c+1]
            if s == 1:
                ok = False
                break

        if ok:
            press = p
            break

    out = [' '.join(map(str, row)) for row in press]
    sys.stdout.write('\n'.join(out))

